/**
 * @file src/lib/farmThreatCombat.ts
 * Farm threat combat — enemy build, fixed base stats + win escalation.
 */

import { Creature } from '../../Creature.ts';
import { RARITY } from '../../constants/core.ts';
import { POKEMON_SECONDARY_TYPES } from '../../constants/core.ts';
import {
    MILTANK_FARM_THREATS,
    ROCKET_COMBAT_BASE,
    getPredatorCombatBaseProfile,
    type FarmThreatCombatProfile,
} from '../../constants/balance/miltankFarmThreats.ts';
import { pickTrainerMoves } from './trainerMovesets.ts';
import type { CreatureData } from '../types/creature.js';
import type { GameRuntime } from '../types/game.js';
import type { FarmThreatApproach } from './miltankFarmThreats.ts';
import type { MiltankFarmState } from './miltankFarmLogic.ts';

export interface FarmThreatCombatEnemyMeta {
    species: string;
    threatLevel: number;
    type: 'predator' | 'rocket';
}

export function isFarmThreatCombatActive(game: GameRuntime | null | undefined): boolean {
    return !!(game?.gymTrainerState?.active && game.gymTrainerState.isFarmThreat);
}

/** Re-pin the ephemeral guardian clone as the active combat fighter. */
export function pinFarmThreatFighter(game: GameRuntime): void {
    if (!isFarmThreatCombatActive(game)) return;
    const fighter = game._farmThreatFighter;
    if (fighter) game.currentPlayerCreature = fighter;
}

export function getFarmThreatCombatSpecies(approach: FarmThreatApproach): string {
    if (approach.type === 'rocket') {
        return MILTANK_FARM_THREATS.rocketCombatSpecies;
    }
    return approach.species;
}

export function getEffectiveThreatCombatWins(threatCombatWins: number): number {
    const raw = Math.max(0, Math.floor(Number(threatCombatWins) || 0));
    return Math.min(MILTANK_FARM_THREATS.threatCombatMaxWins, raw);
}

export function getThreatCombatBaseProfile(approach: FarmThreatApproach): FarmThreatCombatProfile {
    if (approach.type === 'rocket') return ROCKET_COMBAT_BASE;
    return getPredatorCombatBaseProfile(approach.species);
}

export function getThreatCombatEscalation(threatCombatWins: number): {
    levelBonus: number;
    statMultBonus: number;
} {
    const wins = getEffectiveThreatCombatWins(threatCombatWins);
    return {
        levelBonus: wins * MILTANK_FARM_THREATS.threatCombatLevelPerWin,
        statMultBonus: wins * MILTANK_FARM_THREATS.threatCombatStatMultPerWin,
    };
}

export function getFarmThreatCombatLevel(
    approach: FarmThreatApproach,
    threatCombatWins: number,
): number {
    const base = getThreatCombatBaseProfile(approach);
    const { levelBonus } = getThreatCombatEscalation(threatCombatWins);
    return Math.min(
        MILTANK_FARM_THREATS.threatCombatMaxEnemyLevel,
        base.combatBaseLevel + levelBonus,
    );
}

export function getFarmThreatStatMult(
    approach: FarmThreatApproach,
    threatCombatWins: number,
): number {
    const base = getThreatCombatBaseProfile(approach);
    const { statMultBonus } = getThreatCombatEscalation(threatCombatWins);
    return base.combatBaseStatMult + statMultBonus;
}

export function createFarmThreatEnemyCreature(
    approach: FarmThreatApproach,
    threatCombatWins: number,
    findType?: (name: string) => string,
): CreatureData {
    const species = getFarmThreatCombatSpecies(approach);
    const primaryType = findType ? findType(species) : 'dark';
    const secondaryType = POKEMON_SECONDARY_TYPES[species] ?? null;
    const level = getFarmThreatCombatLevel(approach, threatCombatWins);
    const creature = new Creature(
        species,
        primaryType,
        level,
        RARITY.RARE,
        true,
        false,
        secondaryType,
        false,
        false,
    );
    creature.currentMoves = pickTrainerMoves(species, primaryType, null, { ensureTypeDiversity: true });
    const mult = getFarmThreatStatMult(approach, threatCombatWins);
    creature.maxHp = Math.floor(creature.maxHp * mult);
    creature.attack = Math.floor(creature.attack * mult);
    creature.spattack = Math.floor(creature.spattack * mult);
    creature.defense = Math.floor(creature.defense * mult);
    creature.spdefense = Math.floor(creature.spdefense * mult);
    creature.speed = Math.floor(creature.speed * mult);
    creature.currentHp = creature.maxHp;
    (creature as CreatureData & { isGymTrainer?: boolean }).isGymTrainer = true;
    creature.heal?.();
    creature.actionGauge = 0;
    return creature as CreatureData;
}

export function adjustThreatIntensity(state: MiltankFarmState, delta: number): void {
    const current = Math.max(0, Math.floor(Number(state.threatCombatWins) || 0));
    state.threatCombatWins = Math.max(
        0,
        Math.min(MILTANK_FARM_THREATS.threatCombatMaxWins, current + delta),
    );
}

export function recordThreatCombatWin(state: MiltankFarmState): void {
    adjustThreatIntensity(state, 1);
}

export function recordThreatCombatLoss(state: MiltankFarmState): void {
    adjustThreatIntensity(state, -1);
}

export function cloneGuardianForCombat(creature: CreatureData): CreatureData {
    const snapshot = typeof creature.serialize === 'function'
        ? creature.serialize()
        : JSON.parse(JSON.stringify(creature)) as CreatureData;
    const fighter = Creature.deserialize(snapshot) as CreatureData;
    if (typeof fighter.heal === 'function') {
        fighter.heal();
    } else if (fighter.maxHp != null) {
        fighter.currentHp = fighter.maxHp;
        if (fighter.mainAccountCurrentHp != null) {
            fighter.mainAccountCurrentHp = fighter.maxHp;
        }
    }
    fighter.clearStatusEffect?.();
    fighter.actionGauge = 0;
    return fighter;
}

export function findFarmThreatGuardianSource(
    game: GameRuntime,
    guardianUid: string,
): CreatureData | null {
    const uid = String(guardianUid || '');
    if (!uid) return null;
    for (const list of [game.playerTeam, game.storage, game.pension]) {
        if (!Array.isArray(list)) continue;
        const found = list.find((c) => c && String(c.uid || '') === uid);
        if (found) return found;
    }
    const assignments = game.miltankFarmState?.guardianAssignments;
    if (Array.isArray(assignments)) {
        for (const assignment of assignments) {
            const creature = assignment?.creature;
            if (creature && String(creature.uid || '') === uid) return creature;
        }
    }
    return null;
}

export function syncFarmThreatFighterHpToSource(
    game: GameRuntime,
    fighter: CreatureData,
    guardianUid: string,
): void {
    const source = findFarmThreatGuardianSource(game, guardianUid);
    if (!source) return;
    const hp = Math.max(0, Math.floor(Number(fighter.currentHp) || 0));
    const maxHp = Math.max(1, Math.floor(Number(source.maxHp) || hp || 1));
    source.currentHp = Math.min(maxHp, hp);
    if (source.mainAccountCurrentHp != null) {
        source.mainAccountCurrentHp = Math.min(maxHp, hp);
    }
}

export function resetFarmThreatFighterCombatStacks(creature: CreatureData): void {
    creature.sentinelleStacks = 0;
    creature.berserkStacks = 0;
    creature._acharnementStacks = 0;
    creature._acharnementLastTarget = null;
    creature._secondSouffleUsed = false;
    if (creature.passiveTalent === 'abri') creature._abriReady = true;
    creature.clearStatusEffect?.();
}

export function resolveFarmThreatGuardianFromRoster(
    state: MiltankFarmState,
    pastureUid: string,
    source: 'assigned' | 'storage' | 'team' | 'pension',
    index: number,
    rosterCreature?: CreatureData | null,
): CreatureData | null {
    if (source === 'assigned') {
        const assignment = (state.guardianAssignments ?? []).find((a) => a.pastureUid === pastureUid);
        return assignment?.creature ?? null;
    }
    return rosterCreature ?? null;
}
